package com.arjunren.loan.service;
import com.arjunren.loan.domain.Role; import com.arjunren.loan.dto.Dtos.*; import com.arjunren.loan.entity.*; import com.arjunren.loan.exception.DomainException; import com.arjunren.loan.repository.*; import com.arjunren.loan.security.TokenHash; import java.security.SecureRandom; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService{private final UserRepository users;private final AuthTokenRepository tokens;private final PasswordEncoder encoder;private final long ttl;private final SecureRandom random=new SecureRandom();public AuthService(UserRepository u,AuthTokenRepository t,PasswordEncoder e,@Value("${app.security.token-ttl-minutes}")long ttl){users=u;tokens=t;encoder=e;this.ttl=ttl;}@Transactional public UserResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new DomainException(HttpStatus.CONFLICT,"Email already exists");return UserResponse.of(users.save(new AppUser(email,encoder.encode(r.password()),r.name().trim(),Role.CUSTOMER)));}@Transactional public TokenResponse login(LoginRequest r){var u=users.findByEmailIgnoreCase(r.email().trim()).orElse(null);String dummy="$2a$12$7ix4QV/fLm5YCYc8FjmwUOe0wIQFkwSoDvgOL1z9uQkC7B/LBkP3q";boolean ok=encoder.matches(r.password(),u==null?dummy:u.getPasswordHash());if(u==null||!u.isActive()||!ok)throw new DomainException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect");byte[]b=new byte[32];random.nextBytes(b);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(b);Instant expires=Instant.now().plusSeconds(ttl*60);tokens.save(new AuthToken(TokenHash.sha256(raw),u,expires));return new TokenResponse(raw,"Bearer",expires,UserResponse.of(u));}@Transactional public void logout(String raw){tokens.findByTokenHash(TokenHash.sha256(raw)).ifPresent(t->{if(t.getRevokedAt()==null)t.revoke();});}}

